int main(){try{EntryWorld w;auto access=w.authority();auto before=encode_common_state(w.common.state());auto own=access.governance_authority_for_acceptance(w.authority_id,"worker",w.common.revision());check(own.ok,"Own real delivered invitation stopped working");auto other=access.governance_authority_for_acceptance(w.authority_id,"official",w.common.revision());auto unknown=access.governance_authority_for_acceptance("unseen-authority","official",w.common.revision());std::cout<<"AUTHORITY actual_foreign="<<other.error.original.code<<" unknown="<<unknown.error.original.code<<'\n';const bool authority_private=!other.ok&&!unknown.ok&&other.error.original.code=="GovernanceAuthorityNotKnown"&&unknown.error.original.code==other.error.original.code;check(compare_boundary(before,encode_common_state(w.common.state())).exact(),"Authority visibility probe mutated common");auto started=need(w.begin(),"Actual accepted task fixture");w.refresh();before=encode_common_state(w.common.state());auto foreign_cancel=preview_governance_business(w.read(),"official",GovernanceCancelCommand{started.task_id,w.common.revision()});auto unknown_cancel=preview_governance_business(w.read(),"official",GovernanceCancelCommand{"unseen-task",w.common.revision()});auto own_cancel=preview_governance_business(w.read(),"worker",GovernanceCancelCommand{started.task_id,w.common.revision()});std::cout<<"CANCEL actual_foreign="<<foreign_cancel.error.original.code<<" unknown="<<unknown_cancel.error.original.code<<" own_ok="<<own_cancel.ok<<'\n';const bool task_private=!foreign_cancel.ok&&!unknown_cancel.ok&&foreign_cancel.error.original.code=="TaskNotKnown"&&unknown_cancel.error.original.code==foreign_cancel.error.original.code;check(own_cancel.ok,"Own exact active task cancellation was blocked");check(compare_boundary(before,encode_common_state(w.common.state())).exact(),"Cancellation visibility probe mutated common");if(!authority_private||!task_private){std::cerr<<"GOVERNANCE_COMMAND_PRIVACY FAIL authority="<<authority_private<<" task="<<task_private<<'\n';return 1;}std::cout<<"GOVERNANCE_COMMAND_PRIVACY "<<checks<<" checks 0 failures; foreign and absent sources agree, own sources stay usable\n";return 0;}catch(const std::exception& e){std::cerr<<"GOVERNANCE_COMMAND_PRIVACY FAIL "<<e.what()<<'\n';return 1;}}
